// job-ingest answers with ONE item carrying the whole queue. Fan it out so each
// posting is its own item — one bad inference then costs one posting, not the run.
const res = $input.first().json;
if (!res || res.ok !== true) {
  throw new Error('job-ingest pending failed: ' + JSON.stringify(res).slice(0, 300));
}
const pending = res.pending || [];

// An empty queue is the normal steady state, not a failure. Everything gated has
// already been scored. Returning [] ends the run quietly; throwing here would
// paint a red execution every 30 minutes and train everyone to ignore them.
if (pending.length === 0) return [];

return pending.map((p) => ({ json: p }));

