// --- node body ---
// One prompt per pending posting. The catalog handed to the model carries id,
// slot and tags — never content: the prose is what the edge function assembles
// with, and it has no reason to travel to a Docker container or into a context
// window.
const MODEL = 'qwen2.5:latest';

const out = [];
for (const item of $input.all()) {
  const p = item.json;
  const modules = p.modules || [];
  const built = buildEvalPrompt(p.posting || {}, p.profile || {}, modules);
  out.push({
    json: {
      match_id: p.match_id,
      posting_id: p.posting_id,
      title: (p.posting && p.posting.title) || '',
      model: MODEL,
      // The real ids, kept beside the request so the parser can filter the
      // model's answer against them rather than against anything it returned.
      module_ids: modules.map((m) => m.id),
      request: {
        model: MODEL,
        stream: false,
        // Ollama's grammar-constrained JSON mode. Not a guarantee — a 7B model
        // still wraps output in fences often enough that parseEvalResponse
        // slices first-brace-to-last-brace anyway.
        format: 'json',
        options: {
          // This is a classification. Creativity here is just variance in a
          // number a human is going to sort by.
          temperature: 0.1,
          num_ctx: 8192,
        },
        messages: [
          { role: 'system', content: built.system },
          { role: 'user', content: built.user },
        ],
      },
    },
  });
}
return out;

