// --- node body ---
// A failed inference emits NOTHING for that item, so no evaluate_result is
// posted, so the match keeps score IS NULL and comes back on the next pass. That
// is why the Ollama node continues on fail: a 300 s timeout on posting three must
// not discard the four that already succeeded.
//
// Note the pairing is by index. The Ollama node runs one item at a time and n8n
// preserves item order even for a failed one, so index i here is index i there.
const prompts = $('Build Prompt').all();
const queue = $('Split Pending').all();

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const meta = (prompts[i] && prompts[i].json) || {};
  const raw = items[i].json || {};
  const text = (raw.message && raw.message.content) || raw.response || '';
  if (raw.error || !text) continue;

  const parsed = parseEvalResponse(text, { moduleIds: meta.module_ids || [] });
  if (!parsed.ok) continue;

  const modules = (queue[i] && queue[i].json && queue[i].json.modules) || [];
  const plan = planFromVerdict(parsed.verdict, modules);

  // No body is assembled here. job-ingest does that, because the module prose
  // never left Supabase — see EVALUATION.md, "the one rule".
  out.push({
    json: {
      action: 'evaluate_result',
      user_id: $env.NEXUS_USER_ID,
      match_id: meta.match_id,
      model: meta.model,
      verdict: Object.assign({}, parsed.verdict, { module_plan: plan }),
    },
  });
}
return out;
